import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Combate Legacy y Modern","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/legacy-and-modern.md","filePath":"es/game-design/combat/legacy-and-modern.md"}'),n={name:"es/game-design/combat/legacy-and-modern.md"};function d(s,e,r,c,l,m){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="legacy-and-modern-combat" tabindex="-1">Combate Legacy y Modern <a class="header-anchor" href="#legacy-and-modern-combat" aria-label="Enlace permanente a &quot;Combate Legacy y Modern&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Los ejemplos numéricos son hipótesis de prototipo, no equilibrio definitivo. <strong>Implementación/disponibilidad:</strong> no establecida para estas mecánicas. <strong>Verificación:</strong> revisión documental, sin prototipo jugable. <strong>Revisión:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a> · <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a></p><h2 id="definitions-and-design-status" tabindex="-1">Definiciones y estado del diseño <a class="header-anchor" href="#definitions-and-design-status" aria-label="Enlace permanente a &quot;Definiciones y estado del diseño&quot;">​</a></h2><p><strong>Legacy Combat</strong> significa cadencia clásica de ataque automático. <strong>Modern Combat</strong> significa cadencia de ataque activada por el jugador. Ambos comienzan con selección explícita de objetivo (el doble clic clásico es un ejemplo); la selección de objetivo no los distingue. Usar estos nombres como terminología principal para jugadores. «Reactive» describe antecedentes de propuestas o una respuesta defensiva, no un tercer modo.</p><p>Modern es la <strong>dirección de diseño experimental preferida, todavía con estado Propuesto</strong>, pendiente de prototipos jugables. Legacy sigue compatible en el diseño propuesto como alternativa competitiva por accesibilidad, familiaridad y nostalgia. Esto no afirma que ya estén implementados el marco nuevo de dos modos ni sus acciones compartidas.</p><p>La baseline automática anterior con estado Aceptado sigue siendo el fundamento registrado del experimento existente. Batch 05 aclara la alternativa futura prevista en lugar de exigir a todos hacer clic en cada golpe. No eleva silenciosamente Modern a Aceptado ni sustituye la implementación actual. La aceptación formal, el cambio de modo y la relación con contratos existentes de tiempos requieren decisiones posteriores.</p><h2 id="shared-economy-different-initiation" tabindex="-1">Economía compartida, inicio diferente <a class="header-anchor" href="#shared-economy-different-initiation" aria-label="Enlace permanente a &quot;Economía compartida, inicio diferente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cuestión</th><th>Legacy</th><th>Modern</th></tr></thead><tbody><tr><td>Objetivo</td><td>Seleccionar explícitamente primero</td><td>Mismo requisito de selección</td></tr><tr><td>Inicio básico</td><td>Siguiente golpe automático válido del arma en condiciones espaciales válidas</td><td>Una entrada de ataque válida inicia inmediatamente la acción disponible; ningún temporizador automático gobierna el inicio</td></tr><tr><td>Special Attack ofensivo</td><td>Encolar para el siguiente golpe legacy válido; cancelar/cambiar solo cuando se permita</td><td>Activar cuando esté disponible, respetando preparación y wind-up</td></tr><tr><td>Respuesta defensiva</td><td>Entrada manual inmediata, no retenida hasta un golpe</td><td>Misma entrada inmediata sujeta a elegibilidad de la acción</td></tr><tr><td>Reglas subyacentes</td><td>Física de armas, alcance, costes de recursos, recuperación, interacción de armadura y acciones aprendidas compartidos</td><td>Mismas reglas y valores base</td></tr><tr><td>Compromiso principal</td><td>Menos control temporal, cadencia predecible y oportunidades de anticipación</td><td>Tiempos precisos de inicio/liberación y responsabilidad sobre un ritmo sostenible</td></tr><tr><td>Política de poder</td><td>Sin penalización oculta de daño ni desventaja gratuita de RNG</td><td>Sin bonificación arbitraria oculta de stats ni ataques más rápidos gratuitos</td></tr></tbody></table><p>Un inicio inmediato no es un impacto inmediato. La acción sigue asumiendo sus compromisos de stamina, wind-up, fase activa y recuperación. «Válido» incluye disponibilidad, objetivo, condiciones espaciales y reglas de recursos/recuperación resueltas por el servidor. Los costes de entradas rechazadas, cambios de cola y cancelaciones siguen sin decidirse.</p><h2 id="cadence-and-bursts" tabindex="-1">Cadencia y ráfagas <a class="header-anchor" href="#cadence-and-bursts" aria-label="Enlace permanente a &quot;Cadencia y ráfagas&quot;">​</a></h2><p>La cadencia Legacy debería considerar recuperación/clase del arma, manejo, stamina/fatiga actual y DEX acotada; no debe definirse solo mediante DEX. <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html#legacy-test">Batch 06</a> selecciona una fórmula acotada de cadencia con estado Experimental para tres armas; no se acepta ninguna fórmula definitiva.</p><p>Modern puede crear mayor densidad de acciones a corto plazo al elegir el inicio en lugar de esperar a un golpe automático. Las ráfagas de <strong>2–3+ acciones son casos de prueba ilustrativos</strong>, no combos legales garantizados. Las acciones repetidas deben respetar stamina/recuperación; encadenar demasiado rápido debería degradar el rendimiento. <a href="/Syrolands-Public/es/game-design/combat/flow.html">Flow</a> explora un ritmo sostenible en lugar de la máxima frecuencia de entradas.</p><p>Ambos modos usan las mismas definiciones de acciones y los mismos valores subyacentes. Los ajustes de Flow con estado Propuesto son compromisos explícitos dependientes del estado, no una ventaja general del modo sin documentar. Su equidad y la competitividad Legacy requieren pruebas de juego; valores base iguales no demuestran por sí solos equilibrio.</p><h2 id="archery-and-ranged-actions" tabindex="-1">Arquería y acciones a distancia <a class="header-anchor" href="#archery-and-ranged-actions" aria-label="Enlace permanente a &quot;Arquería y acciones a distancia&quot;">​</a></h2><p>Los ataques básicos a distancia no deberían exigir un minijuego de tiempos que perjudique a un modo. La precisión compartida puede depender de Archery, distancia, movimiento del objetivo, movimiento del tirador, preparación de puntería, manejo del arma y fatiga/stamina.</p><table tabindex="0"><thead><tr><th>Caso a distancia</th><th>Legacy</th><th>Modern</th></tr></thead><tbody><tr><td>Disparo básico</td><td>Tensado/liberación sigue automáticamente la cadencia de ataque</td><td>El jugador controla la liberación; detenerse/mantener puntería puede mejorar probabilidad/consistencia mediante factores compartidos</td></tr><tr><td>SA con medidor de tiempos, como el ejemplo Precision Shot</td><td>Preparar/almacenar el mismo resultado del minijuego; liberar en la siguiente cadencia válida a distancia</td><td>Completar el mismo minijuego y ejecutar sujeto a reglas de acción</td></tr></tbody></table><p>Ninguno recibe una ventaja gratuita de RNG. Caducidad del resultado almacenado, cambios de objetivo, movimiento al apuntar, cancelación y reemplazo de cola siguen sin resolverse; el minijuego no se exige para todos los disparos ni se selecciona como experiencia implementada.</p><h2 id="authority-and-unresolved-contracts" tabindex="-1">Autoridad y contratos sin resolver <a class="header-anchor" href="#authority-and-unresolved-contracts" aria-label="Enlace permanente a &quot;Autoridad y contratos sin resolver&quot;">​</a></h2><p>El cliente envía intención de objetivo/acción. El servidor valida tiempos, alcance, LOS, recursos, recuperación, impacto real y efectos; la información sincronizada y la presentación siguen su estado aprobado. Terminar una animación nunca autoriza ataques. Llegada de entradas/latencia, manejo de entradas duplicadas/rechazadas, solapamiento de acciones, caducidad de cola, cambio de modos y accesibilidad/reasignación necesitan contratos explícitos. No se asigna paquete, tecla, temporizador ni política de compensación.</p><p>Consultar <a href="/Syrolands-Public/es/game-design/combat/actions.html">acciones</a>, <a href="/Syrolands-Public/es/game-design/combat/reach-and-spacing.html">alcance</a>, <a href="/Syrolands-Public/es/game-design/characters/familiarity.html">Familiarity</a> y <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">estado del combate</a>.</p>',21)])])}const g=a(n,[["render",d]]);export{u as __pageData,g as default};
